from __future__ import annotations

import typing

from ctc import spec


def get_binary_format(data: spec.BinaryInteger) -> spec.BinaryFormat:
    if isinstance(data, bytes):
        return 'binary'
    elif isinstance(data, str):
        if data.startswith('0x'):
            return 'prefix_hex'
        else:
            return 'raw_hex'
    elif isinstance(data, int):
        return 'integer'
    else:
        raise Exception('could not detect format')


def get_binary_n_bytes(data: spec.BinaryInteger) -> int:

    if isinstance(data, bytes):
        return len(data)
    elif isinstance(data, str):
        if len(data) % 2 != 0:
            raise Exception('hex data must have even number of characters')
        if data.startswith('0x'):
            return int(len(data) / 2) - 1
        else:
            return int(len(data) / 2)
    elif isinstance(data, int):
        # adapted from https://stackoverflow.com/a/30375198
        if data < 0:
            raise Exception('only positive integers allowed')
        return (data.bit_length() + 7) // 8
    else:
        raise Exception('unknown data type: ' + str(data))


#
# # binary data manipulation
#


@typing.overload
def convert(
    data: spec.BinaryInteger,
    output_format: typing.Literal['binary'],
    *,
    n_bytes: int | None = None,
) -> bytes:
    ...


@typing.overload
def convert(
    data: spec.BinaryInteger,
    output_format: typing.Literal['integer'],
    *,
    n_bytes: int | None = None,
) -> int:
    ...


@typing.overload
def convert(
    data: spec.BinaryInteger,
    output_format: typing.Optional[typing.Literal['prefix_hex', 'raw_hex']],
    *,
    n_bytes: int | None = None,
) -> str:
    ...


def convert(
    data: spec.BinaryInteger,
    output_format: typing.Optional[spec.BinaryFormat] = None,
    *,
    n_bytes: int | None = None,
) -> spec.BinaryInteger:
    """convert {hex str or bytes} into {hex str or bytes}

    function should not be used with general text data

    ## Data Types
    - 'prefix_hex': hex str with 0x prefix included
    - 'raw_hex': hex str without 0x prefix included
    - 'binary': bytes

    :data: binary data
    :output_format: str name of output format
    """

    if output_format is None:
        output_format = 'prefix_hex'

    if isinstance(data, str):
        if data.startswith('0x'):
            raw_data = data[2:]
        else:
            raw_data = data

        if n_bytes is not None and len(raw_data) / 2 != n_bytes:
            raise Exception('data does not have target length')

        if output_format == 'prefix_hex':
            return '0x' + raw_data
        elif output_format == 'raw_hex':
            return raw_data
        elif output_format == 'binary':
            if len(raw_data) % 2 == 1:
                raw_data = '0' + raw_data
            return bytes.fromhex(raw_data)
        elif output_format == 'integer':
            return int(data, 16)
        else:
            raise Exception('invalid output_format: ' + str(output_format))

    elif isinstance(data, bytes):

        if n_bytes is not None and len(data) != n_bytes:
            raise Exception('data does not have target length')

        if output_format == 'binary':
            return data
        elif output_format == 'prefix_hex':
            return '0x' + data.hex()
        elif output_format == 'raw_hex':
            return data.hex()
        elif output_format == 'integer':
            return int.from_bytes(data, 'big')
        else:
            raise Exception('invalid output_format: ' + str(output_format))

    elif isinstance(data, int):

        if data < 0:
            raise Exception('only positive integers allowed')

        if output_format == 'integer':

            return data

        else:

            if n_bytes is None:
                n_bytes = get_binary_n_bytes(data)
                keep_leading_0 = False
            else:
                keep_leading_0 = True
            as_bytes = data.to_bytes(n_bytes, 'big')

            if output_format == 'binary':
                return as_bytes
            elif output_format in ['prefix_hex', 'raw_hex']:
                as_hex = as_bytes.hex()
                if not keep_leading_0:
                    as_hex = as_hex.lstrip('0')
                    if data == 0:
                        as_hex = '0'
                if output_format == 'prefix_hex':
                    return '0x' + as_hex
                else:
                    return as_hex
            else:
                raise Exception('invalid output_format: ' + str(output_format))

    else:

        raise Exception('unknown input data format: ' + str(type(data)))


def add_binary_pad(
    data: spec.BinaryInteger,
    *,
    pad_side: typing.Literal['left', 'right', None] = None,
    padded_size: int | None = None,
) -> spec.BinaryInteger:
    """add pad of zeros to left or right side of binary data"""

    # default arguments
    if pad_side is None:
        pad_side = 'left'
    if padded_size is None:
        padded_size = 32

    # determine pad bytes
    binary_format = get_binary_format(data)
    data_bytes = get_binary_n_bytes(data)
    if padded_size < data_bytes:
        raise Exception('pad size too small for data')
    pad_bytes = padded_size - data_bytes

    if binary_format == 'binary':

        data = typing.cast(bytes, data)

        if pad_side == 'left':
            return bytes(0) * pad_bytes + data
        elif pad_side == 'right':
            return data + bytes(0) * pad_bytes
        else:
            raise Exception('invalid pad side: ' + str(pad_side))

    elif binary_format == 'prefix_hex':

        data = typing.cast(str, data)

        if pad_side == 'left':
            return '0x' + '0' * 2 * pad_bytes + data[2:]
        elif pad_side == 'right':
            return data + '0' * 2 * pad_bytes
        else:
            raise Exception('invalid pad side: ' + str(pad_side))

    elif binary_format == 'raw_hex':

        data = typing.cast(str, data)

        if pad_side == 'left':
            return '0' * 2 * pad_bytes + data
        elif pad_side == 'right':
            return data + '0' * 2 * pad_bytes
        else:
            raise Exception('invalid pad side: ' + str(pad_side))

    else:

        raise Exception('invalid binary format: ' + str(binary_format))


def match_format(
    format_this: spec.BinaryInteger,
    like_this: spec.BinaryInteger,
    *,
    match_pad: bool = False,
) -> spec.BinaryInteger:
    """

    will only match left pads, because pad size cannot be reliably determined
    """

    output_format = get_binary_format(like_this)
    output = convert(data=format_this, output_format=output_format)

    if match_pad:
        padded_size = get_binary_n_bytes(like_this)
        output = add_binary_pad(output, padded_size=padded_size)

    return output


def ascii_to_raw_hex(data: str) -> str:
    return data.encode('ascii').hex()


def ascii_to_prefix_hex(data: str) -> str:
    return '0x' + ascii_to_raw_hex(data)


def hex_to_ascii(data: str) -> str:
    import codecs

    if data.startswith('0x'):
        data = data[2:]

    cast_bytes = typing.cast(bytes, data)
    return codecs.decode(cast_bytes, encoding='hex').decode('ascii')

from __future__ import annotations

import typing
from typing_extensions import Literal

from ctc import spec
from . import formats


@typing.overload
def keccak(
    data: spec.BinaryInteger,
    output_format: Literal['integer'],
    *,
    library: typing.Optional[typing.Literal['pysha3', 'pycryptodome']] = None,
) -> int:
    ...


@typing.overload
def keccak(
    data: spec.BinaryInteger,
    output_format: Literal['binary'],
    *,
    library: typing.Optional[typing.Literal['pysha3', 'pycryptodome']] = None,
) -> bytes:
    ...


@typing.overload
def keccak(
    data: spec.BinaryInteger,
    output_format: Literal['prefix_hex', 'raw_hex', None] = 'prefix_hex',
    *,
    library: typing.Optional[typing.Literal['pysha3', 'pycryptodome']] = None,
) -> str:
    ...


def keccak(
    data: spec.BinaryInteger,
    output_format: typing.Optional[spec.BinaryFormat] = 'prefix_hex',
    *,
    library: typing.Optional[typing.Literal['pysha3', 'pycryptodome']] = None,
) -> spec.BinaryInteger:
    """return keccack-256 hash of hex or binary data"""

    # determine library
    if library is None:
        try:
            import sha3  # type: ignore

            library = 'pysha3'

        except ImportError:
            library = 'pycryptodome'

    # convert data to binary
    data = formats.convert(data, 'binary')

    if library == 'pysha3':
        import sha3

        binary = sha3.keccak_256(data).digest()
    elif library == 'pycryptodome':
        from Crypto.Hash import keccak as f_keccak

        binary = f_keccak.new(digest_bits=256, data=data).digest()
    else:
        raise Exception(
            'must choose valid library, either \'pysha3\' or \'pycryptodome\''
        )

    return formats.convert(binary, output_format)


@typing.overload
def keccak_text(
    text: typing.Union[str, bytes],
    output_format: Literal['integer'],
    *,
    library: typing.Optional[typing.Literal['pysha3', 'pycryptodome']] = None,
) -> int:
    ...


@typing.overload
def keccak_text(
    text: typing.Union[str, bytes],
    output_format: Literal['binary'],
    *,
    library: typing.Optional[typing.Literal['pysha3', 'pycryptodome']] = None,
) -> bytes:
    ...


@typing.overload
def keccak_text(
    text: typing.Union[str, bytes],
    output_format: Literal['prefix_hex', 'raw_hex'] = 'prefix_hex',
    *,
    library: typing.Optional[typing.Literal['pysha3', 'pycryptodome']] = None,
) -> str:
    ...


def keccak_text(
    text: typing.Union[str, bytes],
    output_format: spec.BinaryFormat = 'prefix_hex',
    *,
    library: typing.Optional[typing.Literal['pysha3', 'pycryptodome']] = None,
) -> spec.BinaryInteger:
    """return keccack-256 hash of text"""

    if isinstance(text, str):
        text = text.encode()

    return keccak(text, output_format=output_format, library=library)


def keccak256(
    data: spec.BinaryInteger,
    output_format: typing.Optional[spec.BinaryFormat] = 'prefix_hex',
    *,
    library: typing.Optional[typing.Literal['pysha3', 'pycryptodome']] = None,
) -> spec.BinaryInteger:
    """return keccack-256 hash of hex or binary data (alias for keccak)"""
    return keccak(data, output_format=output_format, library=library)

"""
see
- https://eth.wiki/en/fundamentals/rlp
- https://ethereum.org/en/developers/docs/data-structures-and-encoding/rlp/
"""
from __future__ import annotations

import typing

from ctc import spec
from . import formats

if typing.TYPE_CHECKING:
    from typing_extensions import Literal


#
# # encoder
#


@typing.overload
def rlp_encode(
    item: typing.Any,
    output_format: typing.Literal['binary'],
    *,
    str_mode: Literal['auto', 'text', 'hex'] | None = None,
) -> bytes:
    ...


@typing.overload
def rlp_encode(
    item: typing.Any,
    output_format: typing.Literal['integer'],
    *,
    str_mode: Literal['auto', 'text', 'hex'] | None = None,
) -> int:
    ...


@typing.overload
def rlp_encode(
    item: typing.Any,
    output_format: typing.Literal['prefix_hex', 'raw_hex'] = 'prefix_hex',
    *,
    str_mode: Literal['auto', 'text', 'hex'] | None = None,
) -> str:
    ...


def rlp_encode(
    item: typing.Any,
    output_format: spec.BinaryFormat = 'prefix_hex',
    *,
    str_mode: Literal['auto', 'text', 'hex'] | None = 'auto',
) -> spec.BinaryInteger:
    """str_mode specifies how str values should be interpreted"""

    if isinstance(item, int):
        if item == 0:
            item = bytes()
        else:
            item = formats.convert(item, 'binary')

    if isinstance(item, (tuple, list)):
        output = _rlp_encode_list(item, str_mode=str_mode)
    elif isinstance(item, bytes):
        output = _rlp_encode_bytes(item)
    elif isinstance(item, str):
        output = _rlp_encode_str(item, str_mode=str_mode)
    else:
        raise Exception('cannot rlp encode items of type ' + str(type(item)))

    return formats.convert(output, output_format)


def _rlp_encode_bytes(data: bytes) -> bytes:

    data = formats.convert(data, 'binary')

    length = len(data)
    if length == 0:
        return bytes.fromhex('80')
    elif length == 1 and data <= bytes.fromhex('7f'):
        return data
    elif length <= 55:
        prefix = 128 + length
        return formats.convert(prefix, 'binary') + data
    else:
        length_as_bytes = formats.convert(length, 'binary')
        prefix = 183 + len(length_as_bytes)
        return formats.convert(prefix, 'binary') + length_as_bytes + data


def _rlp_encode_list(
    items: typing.Sequence[typing.Any],
    str_mode: Literal['auto', 'text', 'hex'] | None = None,
) -> bytes:

    encoded_items = [
        rlp_encode(item, str_mode=str_mode, output_format='binary')
        for item in items
    ]
    item_lengths = [len(encoded_item) for encoded_item in encoded_items]
    total_payload_length = sum(item_lengths)

    if total_payload_length <= 55:
        prefix = formats.convert(192 + total_payload_length, 'binary')
        output = prefix
        for item in encoded_items:
            output = output + item
        return output

    else:
        bytes_of_length = formats.convert(total_payload_length, 'binary')
        prefix_int = 247 + len(bytes_of_length)
        output = formats.convert(prefix_int, 'binary') + bytes_of_length
        for item in encoded_items:
            output = output + item
        return output


def _rlp_encode_str(
    item: str,
    str_mode: Literal['auto', 'text', 'hex'] | None,
) -> bytes:

    if str_mode == 'auto':
        if item.startswith('0x'):
            str_mode = 'hex'
        else:
            str_mode = 'text'

    if str_mode == 'text':
        as_bytes = item.encode()
    elif str_mode == 'hex':
        as_bytes = formats.convert(item, 'binary')
    else:
        raise Exception('unknown str mode: ' + str(str_mode))

    return _rlp_encode_bytes(as_bytes)


#
# # decoder
#

# use recursive type once mypy#731 gets released
# https://github.com/python/mypy/issues/731

# RLPDecodeTypes = typing.Sequence[typing.Any] | typing.ExtendedBinaryFormat | None
RLPDecodeTypes = typing.Any


def rlp_decode(
    data: spec.Data,
    types: RLPDecodeTypes = None,
) -> typing.Any:
    """decode rlp data

    the types parameter determines how raw data will be decoded in python
    - types is one of:
        1. binary format name: prefix_hex, raw_hex, binary, integer, ascii
        2. list/tuple of binary format names, corresponding to items in rlp list
    """

    data = formats.convert(data, 'binary')
    decoded, remaining = _rlp_decode_chunk(data=data, types=types)
    if len(remaining) > 0:
        raise Exception('data contains extra bytes')
    return decoded


def _rlp_decode_chunk(
    data: bytes,
    types: RLPDecodeTypes,
) -> tuple[typing.Any, bytes]:
    """decode next item chunk in rlp encoded data"""

    if len(data) == 0:
        raise Exception()

    first_byte = data[0]
    if first_byte <= 0xbf:
        return _rlp_decode_primitive_chunk(data, types=types)
    else:
        result = _rlp_decode_list_chunk(data, types=types)
        return result


def _rlp_decode_primitive_chunk(
    data: bytes,
    types: RLPDecodeTypes,
) -> tuple[typing.Any, bytes]:

    first_byte = data[0]

    if first_byte <= 0x7f:
        # data that is single byte less than or equal to 127

        decoded: typing.Any = first_byte.to_bytes(1, 'big')
        remaining = data[1:]

    elif first_byte <= 0xb7:
        # data with length between 0 and 55 bytes

        # get length
        length = first_byte - 0x80

        # get data
        start = 1
        end = 1 + length
        decoded = data[start:end]
        remaining = data[end:]

    elif first_byte <= 0xbf:
        # data longer than 55 bytes

        # get length length
        length_length = first_byte - 0xb7

        # get length
        start = 1
        end = 1 + length_length
        length = int.from_bytes(data[start:end], 'big')

        # get data
        start = 1 + length_length
        end = 1 + length_length + length
        decoded = data[start:end]
        remaining = data[end:]

    else:
        raise Exception('next item in data is not a primitive chunk')

    # convert
    if types is not None:
        if types == 'ascii':
            decoded = decoded.decode()
        else:
            decoded = formats.convert(decoded, types)

    return decoded, remaining


def _rlp_decode_list_chunk(
    data: bytes,
    types: RLPDecodeTypes,
) -> tuple[list[typing.Any], bytes]:

    first_byte = data[0]

    if first_byte <= 0xbf:
        raise Exception('next item in data is not a list chunk')

    elif first_byte <= 0xf7:
        # list with total payload length between 0 and 55 bytes

        # get length
        length = first_byte - 0xc0

        # decode list
        start = 1
        end = 1 + length
        list_payload = data[start:end]

        if len(list_payload) != length:
            raise Exception('data is shorted than specified by header')

        remaining = data[end:]

    else:
        # list with payload longer than 55 bytes

        # get length length
        length_length = first_byte - 0xf7

        # get length
        start = 1
        end = 1 + length_length
        length = int.from_bytes(data[start:end], 'big')

        # decode list
        start = 1 + length_length
        end = 1 + length_length + length
        list_payload = data[start:end]

        if len(list_payload) != length:
            raise Exception('data is shorted than specified by header')

        remaining = data[end:]

    # decode each item of list payload
    output = []
    remaining_payload = list_payload
    index = 0
    while len(remaining_payload) > 0:

        # get type of item
        if isinstance(types, (list, tuple)):
            if index >= len(types):
                raise Exception(
                    'number of types does not match number of list items'
                )
            item_types = types[index]
        elif isinstance(types, str):
            item_types = types
        else:
            item_types = None

        # decode next item in list
        item, remaining_payload = _rlp_decode_chunk(
            remaining_payload,
            types=item_types,
        )
        output.append(item)
        index += 1

    return output, remaining

